namespace TypeScript.Scanner;
[Flags]
public enum FlowFlags : uint
{
    Unreachable = (1u << 0),
    Start = (1u << 1),
    BranchLabel = (1u << 2),
    LoopLabel = (1u << 3),
    Assignment = (1u << 4),
    TrueCondition = (1u << 5),
    FalseCondition = (1u << 6),
    SwitchClause = (1u << 7),
    ArrayMutation = (1u << 8),
    Call = (1u << 9),
    ReduceLabel = (1u << 10),
    Referenced = (1u << 11),
    Shared = (1u << 12),
    Label = BranchLabel | LoopLabel,
    Condition = TrueCondition | FalseCondition,
}

