    public override IEnumerable<SyntaxField> SyntaxFields()
    {
        yield return new("SwitchStatement", "node", SwitchStatement);
        yield return new("ClauseStart", "number", ClauseStart);
        yield return new("ClauseEnd", "number", ClauseEnd);
    }
}

